import { path } from '../path'
import { isomorphicRequireResolve } from './isomorphic-require-resolve'

/**
 * The subset of `@servicenow/aiux-sdk/build` that the SDK consumes. The aiux-sdk
 * package does not ship its own types, so we declare the contract we depend on here.
 */
export interface AiuxSdkBuild {
    buildManifestAndMetadata(opts: {
        projectRoot: string
        fs: unknown
        // biome-ignore lint/suspicious/noExplicitAny: rollup options are passed through opaquely to isomorphic-rollup
        rollup: (options: any) => Promise<unknown>
        verbose?: boolean
        nowConfig?: unknown
    }): Promise<{ metadata: unknown[] }>

    /**
     * Returns the absolute path to the directory where aiux-sdk writes per-record
     * metadata JSON during the prebuild step. The result is a `path.join()` rooted at
     * `projectRoot`; pass `isNowSdkCli: true` when invoked from the now-sdk CLI build.
     */
    getAiuxMetadataOutputDir(opts: { fs: unknown; projectRoot: string; isNowSdkCli?: boolean }): string
}

/**
 * The subset of `@servicenow/aiux-sdk/serve` that the SDK consumes.
 */
export interface AiuxSdkServe {
    serve(opts: {
        args?: Record<string, unknown> | undefined
        // biome-ignore lint/suspicious/noExplicitAny: rollup options are passed through opaquely to isomorphic-rollup
        rollup: (options: any) => Promise<unknown>
        devCookie?: string | undefined
        xUserToken?: string | undefined
        glideOrigin: string
        nowConfig?: unknown
    }): Promise<void>
}

/**
 * Resolves and dynamically imports an aiux-sdk entry point from the user's project
 * (resolved relative to the project's package.json, not the SDK's), trying each
 * candidate specifier in order.
 *
 * FIXME: The karuna-prefixed candidates are a temporary measure to support both
 * @servicenow/aiux/aiux-sdk/* and @servicenow/aiux-sdk/*. This lets us support packages
 * that build inside the Karuna repo and externally to it. This should be revisited next
 * month when the applications currently residing in the Karuna repo are externalized.
 */
const resolveAiuxSdkEntry = async <T>(projectRoot: string, candidates: string[], label: string): Promise<T> => {
    const packageJsonPath = path.join(projectRoot, 'package.json')
    let resolvedPath: string | undefined
    for (const candidate of candidates) {
        try {
            resolvedPath = await isomorphicRequireResolve(candidate, packageJsonPath)
            break
        } catch {
            // try next candidate
        }
    }
    if (!resolvedPath) {
        throw new Error(
            `Could not resolve ${label}. Tried the following packages:\n${candidates.map((c) => `  - ${c}`).join('\n')}`
        )
    }
    return (await require(resolvedPath)) as T
}

/** Resolves `@servicenow/aiux-sdk/build` from the user's project. */
export const resolveAiuxSdkBuild = (projectRoot: string): Promise<AiuxSdkBuild> =>
    resolveAiuxSdkEntry<AiuxSdkBuild>(
        projectRoot,
        ['@servicenow/aiux/aiux-sdk/build', '@servicenow/karuna/aiux-sdk/build', '@servicenow/aiux-sdk/build'],
        'aiux-sdk/build'
    )

/** Resolves `@servicenow/aiux-sdk/serve` from the user's project. */
export const resolveAiuxSdkServe = (projectRoot: string): Promise<AiuxSdkServe> =>
    resolveAiuxSdkEntry<AiuxSdkServe>(
        projectRoot,
        ['@servicenow/aiux/aiux-sdk/serve', '@servicenow/karuna/aiux-sdk/serve', '@servicenow/aiux-sdk/serve'],
        'aiux-sdk/serve'
    )
